static boolean dfs(int u) {
    color[u] = 1;
    for (int v : g.get(u)) {
        if (color[v] == 1) return true;   // back edge -> cycle
        if (color[v] == 0 && dfs(v)) return true;
    }
    color[u] = 2;
    return false;
}
// g: 0->1, 1->2, 2->0 ; called as: System.out.println(dfs(0));

// Edges: 0->1, 1->2, 0->2, 2->3
int[] indeg = {0, 1, 2, 1};
Queue<Integer> q = new ArrayDeque<>();
q.offer(0);
StringBuilder sb = new StringBuilder();
while (!q.isEmpty()) {
    int u = q.poll();
    sb.append(u);
    int[] outs = (u == 0) ? new int[]{1, 2}
            : (u == 1) ? new int[]{2}
            : (u == 2) ? new int[]{3} : new int[]{};
    for (int v : outs) if (--indeg[v] == 0) q.offer(v);
}
System.out.println(sb);

