// Edges: 0->1, 0->2, 2->1
int[] indeg = {0, 2, 1};
Queue<Integer> q = new ArrayDeque<>();
if (indeg[0] == 0) q.offer(0);
StringBuilder sb = new StringBuilder();
while (!q.isEmpty()) {
    int u = q.poll();
    sb.append(u);
    int[] outs = (u == 0) ? new int[]{1, 2}
            : (u == 2) ? new int[]{1} : new int[]{};
    for (int v : outs) if (--indeg[v] == 0) q.offer(v);
}
System.out.println(sb);

